	if len(active) == 0 {
		return
	}

	repoRoot, head, headErr := currentHeadLinkage(ctx)
	divergenceWarnings := make(map[string]string)
	if headErr == nil && repoRoot != "" && head.commitHash != "" {
		divergenceWarnings = computeSessionDivergenceWarnings(repoRoot, active, head)
