func finalizeExitedSessions(ctx context.Context, states []*session.State) int {
	logCtx := logging.WithComponent(ctx, "session")

	strat := GetStrategy(ctx)
	finalized := 0
	for _, st := range states {
		if !st.OwnerExited() {
			continue
		}

		if err := markSessionEnded(ctx, nil, st.SessionID); err != nil {
			logging.Warn(logCtx, "failed to finalize exited session",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
			continue
		}

		// Eagerly condense pending work, mirroring the clean session-stop path.
		// Fail-open: PostCommit retries on the next commit if this fails.
		if err := strat.CondenseAndMarkFullyCondensed(ctx, st.SessionID); err != nil {
			logging.Warn(logCtx, "eager condense on exited session failed",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
		}

		// Reflect the on-disk transition in the in-memory snapshot so the
		// caller's "active" filter drops it.
		now := time.Now()
		st.Phase = session.PhaseEnded
		st.EndedAt = &now
		st.FullyCondensed = true
		finalized++
	}
	return finalized
}

