package cli

import (
	"context"
	"log/slog"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// finalizeExitedSessions finalizes every ACTIVE session in states whose owning
// agent process has exited (clean /exit, crash, kill, terminal close, reboot)
// without a SessionStop hook firing. Each such session is finalized exactly as a
// clean session stop would be: the session-stop transition runs (PhaseEnded +
// EndedAt) and pending work is eagerly condensed.
//
// It mutates the matched in-memory states in place — setting them ended — so
// callers can re-filter/re-render without reloading from disk, and returns the
// number finalized. Each session is best-effort: a failure to mark one ended is
// logged and skipped; a condense failure is logged but the session is still
// counted (PostCommit will retry the condense later).
func finalizeExitedSessions(ctx context.Context, states []*session.State) int {
	logCtx := logging.WithComponent(ctx, "session")

	strat := GetStrategy(ctx)
	finalized := 0
	for _, st := range states {
		if !st.OwnerExited() {
			continue
		}

		if err := markSessionEnded(ctx, nil, st.SessionID); err != nil {
			logging.Warn(logCtx, "failed to finalize exited session",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
			continue
		}

		// Eagerly condense pending work, mirroring the clean session-stop path.
		// Fail-open: PostCommit retries on the next commit if this fails.
		if err := strat.CondenseAndMarkFullyCondensed(ctx, st.SessionID); err != nil {
			logging.Warn(logCtx, "eager condense on exited session failed",
				slog.String("session_id", st.SessionID),
				slog.String("error", err.Error()))
		}

		// Reflect the on-disk transition in the in-memory snapshot so the
		// caller's "active" filter drops it.
		now := time.Now()
		st.Phase = session.PhaseEnded
		st.EndedAt = &now
		st.FullyCondensed = true
		finalized++
	}
	return finalized
}

